"""Save the final blog post as dated markdown with front matter."""
from __future__ import annotations

import re
from datetime import datetime
from pathlib import Path


def get_banner(mock: bool = False) -> str:
    if mock:
        return (
            "<!-- Generated by crewai-research-content-team (Offline Mock LLM) -->\n"
            "<!-- In mock mode this content comes from a bundled offline mock LLM, not Gemini. -->\n\n"
        )
    return (
        "<!-- Generated by crewai-research-content-team (CrewAI + Google Gemini) -->\n\n"
    )


def slugify(text: str, max_len: int = 60) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", (text or "").lower()).strip("-")
    return (slug[:max_len].rstrip("-")) or "untitled"


def write_post(topic: str, content: str, out_dir: str | Path = "output", mock: bool = False) -> Path:
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    date = datetime.now().strftime("%Y-%m-%d")
    path = out / f"{date}-{slugify(topic)}.md"
    provider = "offline-mock-llm" if mock else "google-gemini"
    front_matter = (
        "---\n"
        f"topic: \"{topic}\"\n"
        f"date: {date}\n"
        "pipeline: researcher -> writer (CrewAI sequential)\n"
        f"provider: {provider}\n"
        "---\n\n"
    )
    banner = get_banner(mock=mock)
    path.write_text(front_matter + banner + (content or "").strip() + "\n", encoding="utf-8")
    return path
